<?php declare(strict_types=1);
namespace Modules\PromptEngine\Services;
use Modules\PromptEngine\DTOs\CharacterInputData;
use Modules\PromptEngine\Exceptions\{InvalidCharacterException,UnsupportedPlatformException};
final class CharacterValidationService {
 public function validate(array $data): CharacterInputData { $character=trim((string)($data['character']??'')); if($character===''||mb_strlen($character)!==1||!preg_match('/^[\x{3400}-\x{4DBF}\x{4E00}-\x{9FFF}\x{F900}-\x{FAFF}\x{20000}-\x{2FA1F}]$/u',$character)) throw new InvalidCharacterException('Character must be exactly one CJK ideograph.'); $platform=(string)($data['platform']??config('promptengine.config.default_platform','gemini')); if(!in_array($platform,config('promptengine.config.platforms',[]),true)) throw new UnsupportedPlatformException('Unsupported prompt platform.'); $style=(string)($data['style']??config('promptengine.config.default_style','museum-editorial')); if(!in_array($style,config('promptengine.config.styles',[]),true))$style=(string)config('promptengine.config.default_style','museum-editorial'); $ratio=(string)($data['aspect_ratio']??config('promptengine.config.default_aspect_ratio','2:3')); if(!in_array($ratio,config('promptengine.config.aspect_ratios',[]),true)) throw new InvalidCharacterException('Unsupported aspect ratio.'); $text=(string)($data['text_mode']??config('promptengine.config.default_text_mode','editable-layout')); if(!in_array($text,config('promptengine.config.text_modes',[]),true)) throw new InvalidCharacterException('Unsupported text mode.'); $mode=(string)($data['mode']??'prompt_only'); if(!in_array($mode,config('promptengine.config.modes',[]),true)) throw new InvalidCharacterException('Unsupported mode.'); return new CharacterInputData($character,$platform,$style,$ratio,(string)($data['language']??'vi'),$text,$mode,(bool)($data['save']??false)); }
}
